fields.calculatedFormula:
OR(
  /* Outreach branch */
  AND(
    ISPICKVAL(Account_Status__c, "Outreach"),
    OR(
      /* Pearl/High -> >120 OR blank counts as stale */
      AND(
        OR(
          ISPICKVAL(Lead_Priority__c, "Pearl"),
          ISPICKVAL(Lead_Priority__c, "High")
        ),
        OR(
          ISBLANK(Days_Since_Outreach__c),
          Days_Since_Outreach__c > 120
        )
      ),
      /* Medium -> >360 OR blank counts as stale */
      AND(
        ISPICKVAL(Lead_Priority__c, "Medium"),
        OR(
          ISBLANK(Days_Since_Outreach__c),
          Days_Since_Outreach__c > 360
        )
      )
    )
  ),

  /* Tracking branch */
  AND(
    ISPICKVAL(Account_Status__c, "Tracking"),
    OR(
      /* Pearl/High -> >120 OR blank counts as stale */
      AND(
        OR(
          ISPICKVAL(Lead_Priority__c, "Pearl"),
          ISPICKVAL(Lead_Priority__c, "High")
        ),
        OR(
          ISBLANK(Days_Since_QI__c),
          Days_Since_QI__c > 120
        )
      ),
      /* Medium -> >365 OR blank counts as stale */
      AND(
        ISPICKVAL(Lead_Priority__c, "Medium"),
        OR(
          ISBLANK(Days_Since_QI__c),
          Days_Since_QI__c > 365
        )
      )
    )
  )
)

IF(
  ISBLANK(Head_Count__c),
  "No Data",
  IF(
    Head_Count__c >= 250, "Too Big",
    IF(
      Head_Count__c >= 100, "Extra Large",
      IF(
        Head_Count__c >= 50, "Large",
        IF(
          Head_Count__c >= 20, "Medium",
          IF(
            Head_Count__c >= 10, "Small",
            "Micro"
          )
        )
      )
    )
  )
)
